window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-11eba7e67ebfd8b6"]={"versions": [{"id": "FIG-11eba7e67ebfd8b6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des TTII-Mechanismus (Time Triggered Incremental Interleaved) innerhalb des AUTOSAR ECU State Managers (EcuM, Fixed-Variante). Es beschreibt den internen Kontroll- und Datenfluss bei der Auswertung und Weiterschaltung von Schlafmodi nach dem Verlassen der WAKEUP-Phase.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktionen / Kontrollknoten:\n<ul class=\"fig-list\"><li>Startknoten (from WAKEUP)\n</li><li>Aktion <code>Decrement Divisor Counter</code>\n</li><li>Verzweigungsknoten (Decision Node) mit Bedingungsprüfung <code>[Divisor] Counter &lt;= 1 ?</code>\n</li><li>Aktion <code>Get succeeding sleep mode</code>\n</li><li>Aktion <code>Preload divisor counter for new sleep mode</code>\n</li><li>Endknoten (<code>Activity Final</code>)\n</li></ul>\n</li><li>Datenobjekte und Konfigurationsstrukturen:\n<ul class=\"fig-list\"><li><code>Divisor Counter</code>: Statische Variable (<code>«static variable»</code>), modifiziert durch Dekrementierung und Neuladung.\n</li><li><code>ECUM_TTII_SUCCESSOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), gelesen zur Ermittlung des Folgemodus.\n</li><li><code>ECUM_TTII_DIVISOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), referenziert über Schlafmodusnamen (<code>sleep mode names</code>) zur Bestimmung des neuen Divisorwerts.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt aus dem Zustand <code>WAKEUP</code> in die Aktivität.\n</li><li>In <code>Decrement Divisor Counter</code> wird die statische Variable <code>Divisor Counter</code> dekrementiert.\n</li><li>Auswertung des Verzweigungsknotens:\n<ul class=\"fig-list\"><li>Pfad <code>[no]</code> (Bedingung <code>&lt;= 1</code> nicht erfüllt): Der Kontrollfluss verzweigt direkt zum <code>Activity Final</code>.\n</li><li>Pfad <code>[yes]</code> (Bedingung <code>&lt;= 1</code> erfüllt): \n a. <code>Get succeeding sleep mode</code> liest den nächsten Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code>.\n b. <code>Preload divisor counter for new sleep mode</code> liest den zugehörigen Divisorwert aus <code>ECUM_TTII_DIVISOR_LIST</code> (adressiert über <code>sleep mode names</code>) und setzt die Variable <code>Divisor Counter</code> auf den neuen Vorladewert.\n c. Der Kontrollfluss mündet anschließend im <code>Activity Final</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für die Implementierung der TTII-Zustandsverwaltung im EcuM. Das Diagramm fixiert das deterministische Dekrementieren und Prüfen des Zählers vor dem Wechsel in nachfolgende Schlafmodi. Entwickler müssen sicherstellen, dass <code>Divisor Counter</code> persistent über Aufwachzyklen hinweg als statische Variable gehalten wird und die Lookup-Listen <code>ECUM_TTII_SUCCESSOR_LIST</code> sowie <code>ECUM_TTII_DIVISOR_LIST</code> konsistent vorkonfiguriert sind.</p>"}, {"id": "FIG-36f45b440ad5d339", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des TTII-Mechanismus (Time Triggered Incremental Interleaved) innerhalb des AUTOSAR ECU State Managers (EcuM, Fixed-Variante). Es beschreibt den internen Kontroll- und Datenfluss bei der Auswertung und Weiterschaltung von Schlafmodi nach dem Verlassen der WAKEUP-Phase.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktionen / Kontrollknoten:\n<ul class=\"fig-list\"><li>Startknoten (from WAKEUP)\n</li><li>Aktion <code>Decrement Divisor Counter</code>\n</li><li>Verzweigungsknoten (Decision Node) mit Bedingungsprüfung <code>[Divisor] Counter &lt;= 1 ?</code>\n</li><li>Aktion <code>Get succeeding sleep mode</code>\n</li><li>Aktion <code>Preload divisor counter for new sleep mode</code>\n</li><li>Endknoten (<code>Activity Final</code>)\n</li></ul>\n</li><li>Datenobjekte und Konfigurationsstrukturen:\n<ul class=\"fig-list\"><li><code>Divisor Counter</code>: Statische Variable (<code>«static variable»</code>), modifiziert durch Dekrementierung und Neuladung.\n</li><li><code>ECUM_TTII_SUCCESSOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), gelesen zur Ermittlung des Folgemodus.\n</li><li><code>ECUM_TTII_DIVISOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), referenziert über Schlafmodusnamen (<code>sleep mode names</code>) zur Bestimmung des neuen Divisorwerts.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt aus dem Zustand <code>WAKEUP</code> in die Aktivität.\n</li><li>In <code>Decrement Divisor Counter</code> wird die statische Variable <code>Divisor Counter</code> dekrementiert.\n</li><li>Auswertung des Verzweigungsknotens:\n<ul class=\"fig-list\"><li>Pfad <code>[no]</code> (Bedingung <code>&lt;= 1</code> nicht erfüllt): Der Kontrollfluss verzweigt direkt zum <code>Activity Final</code>.\n</li><li>Pfad <code>[yes]</code> (Bedingung <code>&lt;= 1</code> erfüllt): \n a. <code>Get succeeding sleep mode</code> liest den nächsten Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code>.\n b. <code>Preload divisor counter for new sleep mode</code> liest den zugehörigen Divisorwert aus <code>ECUM_TTII_DIVISOR_LIST</code> (adressiert über <code>sleep mode names</code>) und setzt die Variable <code>Divisor Counter</code> auf den neuen Vorladewert.\n c. Der Kontrollfluss mündet anschließend im <code>Activity Final</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für die Implementierung der TTII-Zustandsverwaltung im EcuM. Das Diagramm fixiert das deterministische Dekrementieren und Prüfen des Zählers vor dem Wechsel in nachfolgende Schlafmodi. Entwickler müssen sicherstellen, dass <code>Divisor Counter</code> persistent über Aufwachzyklen hinweg als statische Variable gehalten wird und die Lookup-Listen <code>ECUM_TTII_SUCCESSOR_LIST</code> sowie <code>ECUM_TTII_DIVISOR_LIST</code> konsistent vorkonfiguriert sind.</p>"}, {"id": "FIG-eb8fa6c6fa86b550", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des TTII-Mechanismus (Time Triggered Incremental Interleaved) innerhalb des AUTOSAR ECU State Managers (EcuM, Fixed-Variante). Es beschreibt den internen Kontroll- und Datenfluss bei der Auswertung und Weiterschaltung von Schlafmodi nach dem Verlassen der WAKEUP-Phase.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktionen / Kontrollknoten:\n<ul class=\"fig-list\"><li>Startknoten (from WAKEUP)\n</li><li>Aktion <code>Decrement Divisor Counter</code>\n</li><li>Verzweigungsknoten (Decision Node) mit Bedingungsprüfung <code>[Divisor] Counter &lt;= 1 ?</code>\n</li><li>Aktion <code>Get succeeding sleep mode</code>\n</li><li>Aktion <code>Preload divisor counter for new sleep mode</code>\n</li><li>Endknoten (<code>Activity Final</code>)\n</li></ul>\n</li><li>Datenobjekte und Konfigurationsstrukturen:\n<ul class=\"fig-list\"><li><code>Divisor Counter</code>: Statische Variable (<code>«static variable»</code>), modifiziert durch Dekrementierung und Neuladung.\n</li><li><code>ECUM_TTII_SUCCESSOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), gelesen zur Ermittlung des Folgemodus.\n</li><li><code>ECUM_TTII_DIVISOR_LIST</code>: Konfigurationsdaten (<code>«configuration data»</code>), referenziert über Schlafmodusnamen (<code>sleep mode names</code>) zur Bestimmung des neuen Divisorwerts.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt aus dem Zustand <code>WAKEUP</code> in die Aktivität.\n</li><li>In <code>Decrement Divisor Counter</code> wird die statische Variable <code>Divisor Counter</code> dekrementiert.\n</li><li>Auswertung des Verzweigungsknotens:\n<ul class=\"fig-list\"><li>Pfad <code>[no]</code> (Bedingung <code>&lt;= 1</code> nicht erfüllt): Der Kontrollfluss verzweigt direkt zum <code>Activity Final</code>.\n</li><li>Pfad <code>[yes]</code> (Bedingung <code>&lt;= 1</code> erfüllt): \n a. <code>Get succeeding sleep mode</code> liest den nächsten Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code>.\n b. <code>Preload divisor counter for new sleep mode</code> liest den zugehörigen Divisorwert aus <code>ECUM_TTII_DIVISOR_LIST</code> (adressiert über <code>sleep mode names</code>) und setzt die Variable <code>Divisor Counter</code> auf den neuen Vorladewert.\n c. Der Kontrollfluss mündet anschließend im <code>Activity Final</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für die Implementierung der TTII-Zustandsverwaltung im EcuM. Das Diagramm fixiert das deterministische Dekrementieren und Prüfen des Zählers vor dem Wechsel in nachfolgende Schlafmodi. Entwickler müssen sicherstellen, dass <code>Divisor Counter</code> persistent über Aufwachzyklen hinweg als statische Variable gehalten wird und die Lookup-Listen <code>ECUM_TTII_SUCCESSOR_LIST</code> sowie <code>ECUM_TTII_DIVISOR_LIST</code> konsistent vorkonfiguriert sind.</p>"}], "trans": [{"from": "FIG-11eba7e67ebfd8b6", "to": "FIG-36f45b440ad5d339", "fr": "R4.0.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bildzuschnitt bzw. Ränder leicht vergrößert (von 804x410 auf 828x420 Pixel), wodurch die untere Beschriftung des Activity-Final-Knotens minimal verschoben bzw. abgeschnitten ist.\n</li></ul>"}, {"from": "FIG-36f45b440ad5d339", "to": "FIG-eb8fa6c6fa86b550", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
